type ColorQuestionSeed = Omit<ColorQuestion, 'category'>;

function inCategory(
  category: ColorQuestion['category'],
  questions: readonly ColorQuestionSeed[],
): readonly ColorQuestion[] {
  return questions.map((question) => ({ ...question, category }));
}

